std::optional<FiscalAssessmentSummary> occupation_fiscal_assessment_result(const CommonStore& common,const OccupationFiscalSettlementState& state,const StableId& id){const auto* p=state.periods.find(id);if(!p||p->due_tick>state.last_step_tick||!header(common,id,occupation_fiscal_period_kind,"local_economy"))return {};return FiscalAssessmentSummary{id,p->policy.jurisdiction_id,p->policy.site_id,p->policy.organization_id,p->policy.source_fact_id,p->due_tick,p->policy.mode,true};}
Outcome<std::optional<FiscalAssessmentSummary>> read_occupation_fiscal_period(const OccupationFiscalSettlementContext& x,const OccupationFiscalSettlementState& state,const StableId& id){auto valid=validate_occupation_fiscal_settlement(x,state);if(!valid.ok)return {false,{},valid.error};return {true,occupation_fiscal_assessment_result(x.common,state,id),{}};}

